/// Kind of transcript entry in a thread conversation. CONTACT (inbound, a person in the conversation), SYSTEM (this product spoke on the channel), DIRECT (the owner spoke on the channel through the console while paused — same word as ThreadMode.DIRECT, one spelling for one idea), WHISPER (in-app steer, never sent to the channel), ACTION (audit line). NOTE the known residue: CONTACT/DIRECT name a DIRECTION while SYSTEM names an AUTHOR. The principled shape is {MESSAGE, WHISPER, ACTION} plus an author field on the entry, deferred because it costs a transcript column.
#[derive(
	Debug, Clone, Copy, PartialEq, Eq, Hash,
	serde::Serialize, serde::Deserialize,
	strum::EnumString, strum::IntoStaticStr, strum::Display,
)]
#[allow(non_camel_case_types)]
pub enum TranscriptKind {
	#[serde(rename = "CONTACT")]
	#[strum(serialize = "CONTACT")]
	CONTACT,
	#[serde(rename = "SYSTEM")]
	#[strum(serialize = "SYSTEM")]
	SYSTEM,
	#[serde(rename = "DIRECT")]
	#[strum(serialize = "DIRECT")]
	DIRECT,
	#[serde(rename = "WHISPER")]
	#[strum(serialize = "WHISPER")]
	WHISPER,
	#[serde(rename = "ACTION")]
	#[strum(serialize = "ACTION")]
	ACTION,
}

/// Detected trait of a registered workspace folder. GIT = a .git repository; CLAUDE_PROJECT = a Claude project marker. A workspace may carry both.
#[derive(
	Debug, Clone, Copy, PartialEq, Eq, Hash,
	serde::Serialize, serde::Deserialize,
	strum::EnumString, strum::IntoStaticStr, strum::Display,
)]
#[allow(non_camel_case_types)]
pub enum WorkspaceBadge {
	#[serde(rename = "GIT")]
	#[strum(serialize = "GIT")]
	GIT,
	#[serde(rename = "CLAUDE_PROJECT")]
	#[strum(serialize = "CLAUDE_PROJECT")]
	CLAUDE_PROJECT,
}
